import { useState, type FormEvent } from "react";
import { Link, useNavigate } from "react-router-dom";
import toast from "react-hot-toast";
import { useAuth } from "../hooks/useAuth";

// Logo is embedded in this file, so no separate public/assets path is needed.
const DEE_LOGO = "data:image/jpeg;base64,";

export default function Login() {
  const { login } = useAuth();
  const navigate = useNavigate();

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (!email.trim() || !password) {
      toast.error("Please enter your email and password.");
      return;
    }

    try {
      setSubmitting(true);
      await login(email.trim(), password);
      toast.success("Login successful!");
      navigate("/dashboard", { replace: true });
    } catch (error: unknown) {
      const message =
        error instanceof Error
          ? error.message
          : "Login failed. Please check your credentials.";
      toast.error(message);
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#F3F6FC] px-4 py-8">
      <div className="w-full max-w-md">
        {/* Actual DEE Piping Systems logo, centred above the login card */}
        <div className="mb-6 flex justify-center">
          <img
            src={DEE_LOGO}
            alt="DEE Piping Systems"
            className="h-auto w-64 max-w-full object-contain"
          />
        </div>

        <div className="rounded-2xl border border-[#DCE6F5] bg-white px-7 py-7 shadow-xl shadow-blue-900/5 sm:px-9">
          <div className="mb-6 text-center">
            <div className="mx-auto mb-4 h-1 w-12 rounded-full bg-[#4F80F5]" />
            <h1 className="text-2xl font-bold text-[#172B4D]">Welcome back</h1>
            <p className="mt-2 text-sm text-slate-500">
              Sign in to your travel management account
            </p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label htmlFor="email" className="mb-1.5 block text-sm font-semibold text-[#344563]">
                Email address
              </label>
              <input
                id="email"
                name="email"
                type="email"
                autoComplete="username"
                required
                value={email}
                onChange={(event) => setEmail(event.target.value)}
                placeholder="Enter your work email"
                className="w-full rounded-lg border border-[#D5E2F5] bg-[#EEF4FF] px-4 py-3 text-sm text-slate-900 outline-none transition focus:border-[#4F80F5] focus:ring-2 focus:ring-[#4F80F5]/20"
              />
            </div>

            <div>
              <label htmlFor="password" className="mb-1.5 block text-sm font-semibold text-[#344563]">
                Password
              </label>
              <div className="relative">
                <input
                  id="password"
                  name="password"
                  type={showPassword ? "text" : "password"}
                  autoComplete="current-password"
                  required
                  value={password}
                  onChange={(event) => setPassword(event.target.value)}
                  placeholder="Enter your password"
                  className="w-full rounded-lg border border-[#D5E2F5] bg-[#EEF4FF] px-4 py-3 pr-16 text-sm text-slate-900 outline-none transition focus:border-[#4F80F5] focus:ring-2 focus:ring-[#4F80F5]/20"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword((current) => !current)}
                  className="absolute right-4 top-1/2 -translate-y-1/2 text-xs font-semibold text-[#4F80F5] hover:text-[#315FD0]"
                >
                  {showPassword ? "Hide" : "Show"}
                </button>
              </div>
            </div>

            <button
              type="submit"
              disabled={submitting}
              className="w-full rounded-lg bg-[#4F80F5] px-4 py-3 text-sm font-semibold text-white shadow-md shadow-blue-500/20 transition hover:bg-[#3D6FE5] disabled:cursor-not-allowed disabled:opacity-60"
            >
              {submitting ? "Signing in..." : "Sign In →"}
            </button>
          </form>

          <p className="mt-6 text-center text-sm text-slate-500">
            Don&apos;t have an account?{" "}
            <Link to="/signup" className="font-semibold text-[#4F80F5] hover:text-[#315FD0]">
              Create an account
            </Link>
          </p>

          <p className="mt-6 text-center text-[11px] text-slate-400">
            © {new Date().getFullYear()} DEE Piping System · All rights reserved
          </p>
        </div>
      </div>
    </div>
  );
}
